prompt --application/shared_components/security/authorizations/is_admin
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(18021322800862247781)
,p_name=>'Is_Admin'
,p_static_id=>'is-admin'
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'plsql_function_body', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    v_role VARCHAR(100);',
    'BEGIN',
    '    SELECT UPPER(TRIM("ROLE"))',
    '    INTO v_role',
    '    FROM "User"',
    '    WHERE UPPER(TRIM("USERNAME")) = UPPER(TRIM(:APP_USER));',
    '',
    '    RETURN v_role IN (''ADMIN'',''ORGANIZER'');',
    'EXCEPTION',
    '    WHEN NO_DATA_FOUND THEN',
    '        RETURN FALSE;',
    '    WHEN OTHERS THEN',
    '        RETURN FALSE;',
    'END;')))).to_clob
,p_error_message=>'Access Denied: You must be an Administrator to view this page.'
,p_version_scn=>'SH256:NHJHK4yAgr1FG2uZ9SQa-Ak7DJmrkgoQ9UxkBagM9M0'
,p_caching=>'BY_COMPONENT'
,p_comments=>'Admin Security'
,p_created_on=>wwv_flow_imp.dz('20260713153529Z')
,p_updated_on=>wwv_flow_imp.dz('20260722010831Z')
,p_created_by=>'KENNYSTONE2006@GMAIL.COM'
,p_updated_by=>'KENNYSTONE2006@GMAIL.COM'
);
