,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    ''Upcoming Events'' AS title, ',
'    COUNT(*) AS value, ',
'    ''fa-calendar-star'' AS icon,',
'    ''#available-events'' AS card_link',
'FROM "EVENT" ',
'WHERE EVENT_DATE >= TRUNC(SYSDATE)',
'',
'UNION ALL ',
'',
'SELECT ',
'    ''My Bookings'' AS title, ',
'    COUNT(*) AS value, ',
'    ''fa-ticket'' AS icon,',
'    APEX_PAGE.GET_URL(p_page => 6) AS card_link',
'FROM "BOOKING" ',
'WHERE USER_ID = (',
'    SELECT USER_ID ',
'    FROM "User" ',
'    WHERE LOWER(USERNAME) = LOWER(:APP_USER) ',
'       OR LOWER(EMAIL)    = LOWER(:APP_USER)',
')'))
,p_lazy_loading=>false
