 p_id=>wwv_flow_imp.id(18843130968686262359)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process form Book Ticket'
,p_static_id=>'process-form-book-ticket'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    v_user_id "User".user_id%TYPE; ',
'BEGIN ',
'    -- 1. Find User ID for the logged-in user',
'    SELECT user_id ',
'    INTO v_user_id ',
'    FROM "User" ',
'    WHERE LOWER(TRIM(username)) = LOWER(TRIM(:APP_USER)); ',
'',
'    -- 2. Execute procedure to record booking',
'    PROC_BOOK_TICKET(',
'        p_user_id   => v_user_id, ',
'        p_ticket_id => TO_NUMBER(:P5_TICKET_ID), ',
'        p_quantity  => NVL(TO_NUMBER(:P5_QUANTITY), 1) ',
'    ); ',
'',
'    -- 3. Pass new booking ID to P5_BOOKING_ID so Page 7 gets it',
'    SELECT MAX(booking_id) ',
'    INTO :P5_BOOKING_ID ',
'    FROM "BOOKING" ',
'    WHERE user_id = v_user_id;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(18843130176768262358)
,p_process_success_message=>'Ticket booked successfully!'
,p_internal_uid=>18843130968686262359
,p_created_on=>wwv_flow_imp.dz('20260716140222Z')
,p_updated_on=>wwv_flow_imp.dz('20260725043854Z')
,p_created_by=>'KENNYSTONE2006@GMAIL.COM'
,p_updated_by=>'KENNYSTONE2006@GMAIL.COM'
);
end;
