wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(18828442511233155540)
,p_plug_name=>'Overview Metrics'
,p_static_id=>'new'
,p_title=>'Overview Metrics'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    ''Total Revenue'' AS title,',
'    ''GHS '' || TO_CHAR(NVL((SELECT SUM(amount) FROM "PAYMENT"), 0), ''999,999.00'') AS card_value,',
'    ''fa-money'' AS icon_class,',
'    ''Total revenue generated across all bookings'' AS subtitle',
'FROM DUAL',
'UNION ALL',
'SELECT ',
'    ''Tickets Sold'' AS title,',
'    TO_CHAR(NVL(SUM(quantity), 0)) AS card_value,',
'    ''fa-ticket'' AS icon_class,',
'    ''Total tickets purchased by attendees'' AS subtitle',
'FROM "BOOKING"',
'UNION ALL',
'SELECT ',
'    ''Active Events'' AS title,',
'    TO_CHAR(COUNT(*)) AS card_value,',
'    ''fa-calendar'' AS icon_class,',
'    ''Total events currently published'' AS subtitle',
'FROM "EVENT";'))
